arguments.content:
const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// ============================================================
// COLOR PALETTE: "Ocean Gradient" adapted for tech/ML
// Primary deep navy: 065A82
// Secondary teal: 1C7293
// Accent mint: 5EEAD4
// Dark midnight: 21295C
// Light background: ECF0F3
// ============================================================
const C = {
  primary: "065A82",
  secondary: "1C7293",
  accent: "5EEAD4",
  midnight: "21295C",
  light: "ECF0F3",
  white: "FFFFFF",
  darkText: "1E293B",
  mutedText: "64748B",
  chart1: "065A82",
  chart2: "1C7293",
  chart3: "5EEAD4",
  chart4: "21295C",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "SmolVLM: Redefining Small and Efficient Multimodal Models";
pres.author = "Hugging Face & Stanford";
pres.subject = "Efficient vision-language models for edge deployment";

// ============================================================
// Helper: rounded rect shadow
// ============================================================
function shadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

// ============================================================
// SLIDE 1 — Title
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.midnight };

  // Decorative accent bar left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.accent },
  });

  // Title
  slide.addText("SmolVLM: Redefining Small and Efficient Multimodal Models", {
    x: 0.7, y: 1.6, w: 8.6, h: 1.4,
    fontSize: 40, fontFace: "Calibri", bold: true,
    color: C.white, align: "left", valign: "middle",
    margin: 0,
  });

  // Subtitle
  slide.addText("Hugging Face & Stanford University", {
    x: 0.7, y: 3.1, w: 8.6, h: 0.5,
    fontSize: 20, fontFace: "Calibri", bold: false,
    color: C.accent, align: "left", valign: "middle",
    margin: 0,
  });

  // One-liner
  slide.addText("Sub-1GB inference. Competitive with models 300× larger. Fully open-source.", {
    x: 0.7, y: 3.7, w: 8.6, h: 0.5,
    fontSize: 16, fontFace: "Calibri Light",
    color: C.white, align: "left", valign: "middle",
    margin: 0,
  });

  // Architecture image on right
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: 6.8, y: 1.3, w: 2.8, h: 2.8,
    sizing: { type: "contain", w: 2.8, h: 2.8 },
  });
}

// ============================================================
// SLIDE 2 — Problem / Motivation
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Large VLMs Are Powerful but Impractical for Edge Deployment", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 32, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Left column: bullets
  slide.addText([
    { text: "State-of-the-art VLMs demand 10–80 GB GPU RAM", options: { bullet: true, breakLine: true } },
    { text: "Mobile and edge devices are limited to 4–16 GB total system memory", options: { bullet: true, breakLine: true } },
    { text: "Cloud dependency raises latency, cost, and privacy concerns", options: { bullet: true, breakLine: true } },
    { text: "Need: compact architectures that preserve capability at sub-1GB scale", options: { bullet: true } },
  ], {
    x: 0.5, y: 1.2, w: 5.0, h: 2.6,
    fontSize: 16, fontFace: "Calibri Light",
    color: C.darkText, align: "left", valign: "top",
    paraSpaceAfter: 10,
  });

  // Right column: stat cards
  const cardW = 3.8, cardH = 1.0;
  const cardX = 6.0;
  const cards = [
    { y: 1.2, label: "Molmo-A1B-7B RAM", value: "27.7 GB", sub: "Best efficient OS baseline" },
    { y: 2.35, label: "Idefics-80B Params", value: "80 B", sub: "300× larger than SmolVLM-256M" },
    { y: 3.5, label: "SmolVLM-256M RAM", value: "0.8 GB", sub: "Batch size 1, competitive accuracy" },
  ];
  cards.forEach((c, i) => {
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: c.y, w: cardW, h: cardH,
      fill: { color: C.white },
      shadow: shadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: c.y, w: 0.08, h: cardH,
      fill: { color: i === 2 ? C.accent : C.primary },
    });
    slide.addText(c.value, {
      x: cardX + 0.2, y: c.y + 0.12, w: cardW - 0.3, h: 0.45,
      fontSize: 28, fontFace: "Calibri", bold: true,
      color: i === 2 ? C.accent : C.primary,
      align: "left", valign: "middle", margin: 0,
    });
    slide.addText(c.label, {
      x: cardX + 0.2, y: c.y + 0.55, w: cardW - 0.3, h: 0.2,
      fontSize: 12, fontFace: "Calibri",
      color: C.mutedText, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(c.sub, {
      x: cardX + 0.2, y: c.y + 0.75, w: cardW - 0.3, h: 0.18,
      fontSize: 10, fontFace: "Calibri Light",
      color: C.mutedText, align: "left", valign: "middle", margin: 0,
    });
  });
}

// ============================================================
// SLIDE 3 — Architecture Overview
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2 Backbone", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 30, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Architecture image
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: 0.5, y: 1.1, w: 9, h: 2.4,
    sizing: { type: "contain", w: 9, h: 2.4 },
  });

  // 4-step pipeline cards below image
  const steps = [
    { n: "1", title: "Image Splitting", desc: "Input image divided into sub-images for local encoding" },
    { n: "2", title: "Vision Encoder", desc: "SigLIP encoder extracts spatial feature maps" },
    { n: "3", title: "Pixel Shuffle", desc: "Space-to-depth rearrangement compresses tokens by r²" },
    { n: "4", title: "SmolLM2 Fusion", desc: "Linear projection + text embeddings → language model" },
  ];
  const stepW = 2.15, stepH = 1.4, gap = 0.17, startX = 0.5;
  steps.forEach((s, i) => {
    const x = startX + i * (stepW + gap);
    const y = 3.7;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: stepW, h: stepH,
      fill: { color: C.white },
      shadow: shadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: stepW, h: 0.08,
      fill: { color: C.primary },
    });
    slide.addText(s.n, {
      x: x + 0.1, y: y + 0.18, w: 0.5, h: 0.4,
      fontSize: 24, fontFace: "Calibri", bold: true,
      color: C.primary, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(s.title, {
      x: x + 0.1, y: y + 0.55, w: stepW - 0.2, h: 0.3,
      fontSize: 14, fontFace: "Calibri", bold: true,
      color: C.darkText, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(s.desc, {
      x: x + 0.1, y: y + 0.85, w: stepW - 0.2, h: 0.45,
      fontSize: 11, fontFace: "Calibri Light",
      color: C.mutedText, align: "left", valign: "top", margin: 0,
    });
  });
}

// ============================================================
// SLIDE 4 — Compute Allocation (Bar Chart)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Smaller Vision Encoders Outperform Larger Ones in Compact VLMs", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 30, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Bar chart
  slide.addChart(pres.charts.BAR, [
    {
      name: "93M SigLIP-B/16",
      labels: ["135M LM", "1.7B LM"],
      values: [100, 100], // normalized relative performance
    },
    {
      name: "428M SigLIP-SO400M",
      labels: ["135M LM", "1.7B LM"],
      values: [92, 110], // underperforms at small LM, slight overhead justified at 1.7B
    },
  ], {
    x: 0.5, y: 1.2, w: 5.5, h: 3.8,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [C.primary, C.accent],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.mutedText,
    valAxisLabelColor: C.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    showLegend: true,
    legendPos: "b",
    title: "Relative Performance by Encoder-LM Pairing",
    showTitle: true,
    titleFontSize: 14,
    titleColor: C.darkText,
  });

  // Right-side insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.4, w: 3.2, h: 3.4,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.4, w: 0.08, h: 3.4,
    fill: { color: C.accent },
  });
  slide.addText("Finding 1", {
    x: 6.5, y: 1.6, w: 2.8, h: 0.4,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Balanced Encoder-LM Compute", {
    x: 6.5, y: 2.0, w: 2.8, h: 0.35,
    fontSize: 14, fontFace: "Calibri", bold: true,
    color: C.darkText, align: "left", valign: "middle", margin: 0,
  });
  slide.addText([
    { text: "A 93M SigLIP-B/16 paired with a 135M LM outperforms a 428M SigLIP-SO400M with the same LM.", options: { breakLine: true } },
    { text: "Only at 1.7B LM scale does the larger encoder justify its ~10% parameter overhead.", options: { breakLine: true } },
    { text: "Implication: allocate compute proportionally; oversized encoders hurt small VLMs.", options: {} },
  ], {
    x: 6.5, y: 2.45, w: 2.8, h: 2.1,
    fontSize: 12, fontFace: "Calibri Light",
    color: C.darkText, align: "left", valign: "top",
    paraSpaceAfter: 8,
  });
}

// ============================================================
// SLIDE 5 — Token Compression (Pixel Shuffle)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16× for Small Models", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 30, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Left: pixel shuffle diagram
  slide.addImage({
    path: "/app/benchmark/assets/figure_6.jpg",
    x: 0.5, y: 1.2, w: 4.2, h: 3.6,
    sizing: { type: "contain", w: 4.2, h: 3.6 },
  });

  // Right: explanation cards
  const cardX = 5.1, cardW = 4.4;

  // Card 1: What is pixel shuffle
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.2, w: cardW, h: 1.5,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.2, w: 0.08, h: 1.5,
    fill: { color: C.primary },
  });
  slide.addText("Mechanism", {
    x: cardX + 0.15, y: 1.35, w: cardW - 0.25, h: 0.3,
    fontSize: 14, fontFace: "Calibri", bold: true,
    color: C.primary, align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Spatial features are rearranged into depth channels, reducing token count by r². At r=4, a 32×32 feature map becomes 8×8 — a 16× reduction.", {
    x: cardX + 0.15, y: 1.7, w: cardW - 0.25, h: 0.9,
    fontSize: 12, fontFace: "Calibri Light",
    color: C.darkText, align: "left", valign: "top", margin: 0,
  });

  // Card 2: Impact
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.9, w: cardW, h: 1.9,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.9, w: 0.08, h: 1.9,
    fill: { color: C.accent },
  });
  slide.addText("Impact on Small VLMs", {
    x: cardX + 0.15, y: 3.05, w: cardW - 0.25, h: 0.3,
    fontSize: 14, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle", margin: 0,
  });
  slide.addText([
    { text: "Larger models use r=2 (4× reduction) — sufficient with bigger LMs.", options: { breakLine: true } },
    { text: "Small VLMs benefit from r=4 (16× reduction), easing attention overhead.", options: { breakLine: true } },
    { text: "Enables longer context and higher effective resolution per token budget.", options: {} },
  ], {
    x: cardX + 0.15, y: 3.4, w: cardW - 0.25, h: 1.3,
    fontSize: 12, fontFace: "Calibri Light",
    color: C.darkText, align: "left", valign: "top",
    paraSpaceAfter: 6,
  });
}

// ============================================================
// SLIDE 6 — Context Length Scaling
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Extending Context from 2K to 16K Tokens Unlocks Higher Image Resolution", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 30, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Left: key stats
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 4.0, h: 3.6,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 0.08, h: 3.6,
    fill: { color: C.secondary },
  });
  slide.addText("Finding 2", {
    x: 0.7, y: 1.5, w: 3.5, h: 0.4,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: C.secondary, align: "left", valign: "middle", margin: 0,
  });

  const statItems = [
    { big: "2K → 16K", label: "Context length extension" },
    { big: "10K → 273K", label: "RoPE base adjustment" },
    { big: "16K", label: "SmolVLM-2.2B context" },
    { big: "8K", label: "256M / 500M context" },
  ];
  statItems.forEach((s, i) => {
    const y = 2.05 + i * 0.85;
    slide.addText(s.big, {
      x: 0.7, y, w: 3.5, h: 0.35,
      fontSize: 22, fontFace: "Calibri", bold: true,
      color: C.darkText, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(s.label, {
      x: 0.7, y: y + 0.35, w: 3.5, h: 0.22,
      fontSize: 11, fontFace: "Calibri Light",
      color: C.mutedText, align: "left", valign: "middle", margin: 0,
    });
  });

  // Right: explanation
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.8, y: 1.3, w: 4.7, h: 3.6,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.8, y: 1.3, w: 0.08, h: 3.6,
    fill: { color: C.accent },
  });
  slide.addText("How It Works", {
    x: 5.0, y: 1.5, w: 4.3, h: 0.4,
    fontSize: 18, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle", margin: 0,
  });
  slide.addText([
    { text: "Increase RoPE base from 10,000 to 273,000 to extend positional encoding range.", options: { breakLine: true } },
    { text: "Fine-tune on mixed long/short-context data to maintain stability across sequence lengths.", options: { breakLine: true } },
    { text: "Performance improves significantly as context grows — more image patches and longer video frames fit within the token budget.", options: { breakLine: true } },
    { text: "Trade-off: smaller variants (256M, 500M) use 8K context; only 2.2B scales to 16K.", options: {} },
  ], {
    x: 5.0, y: 2.05, w: 4.3, h: 2.7,
    fontSize: 13, fontFace: "Calibri Light",
    color: C.darkText, align: "left", valign: "top",
    paraSpaceAfter: 10,
  });
}

// ============================================================
// SLIDE 7 — Benchmark Performance (Data Table)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("SmolVLM Achieves Competitive Performance at Sub-1GB to 4.9GB RAM", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Table
  const tableData = [
    [
      { text: "Capability", options: { fill: { color: C.midnight }, color: C.white, bold: true, align: "center" } },
      { text: "Benchmark", options: { fill: { color: C.midnight }, color: C.white, bold: true, align: "center" } },
      { text: "256M", options: { fill: { color: C.primary }, color: C.white, bold: true, align: "center" } },
      { text: "500M", options: { fill: { color: C.primary }, color: C.white, bold: true, align: "center" } },
      { text: "2.2B", options: { fill: { color: C.primary }, color: C.white, bold: true, align: "center" } },
      { text: "Best Efficient OS", options: { fill: { color: C.midnight }, color: C.white, bold: true, align: "center" } },
    ],
    ["Single-Image", "OCRBench", "52.6%", "61.0%", "72.9%", "54.7% (Molmo)"],
    ["Single-Image", "AI2D", "46.4%", "59.2%", "70.0%", "71.0% (Molmo)"],
    ["Single-Image", "ChartQA", "55.6%", "62.8%", "68.7%", "48.0% (Molmo)"],
    ["Single-Image", "TextVQA", "50.2%", "60.2%", "73.0%", "61.5% (Molmo)"],
    ["Single-Image", "DocVQA", "58.3%", "70.5%", "80.0%", "77.7% (Molmo)"],
    ["Single-Image", "ScienceQA", "73.8%", "80.0%", "89.6%", "87.5% (Molmo)"],
    ["Multi-task", "MMMU", "29.0%", "33.7%", "42.0%", "33.9% (Molmo)"],
    ["Multi-task", "MathVista", "35.9%", "40.1%", "51.5%", "37.6% (Molmo)"],
    ["Multi-task", "MMStar", "34.6%", "38.3%", "46.0%", "43.1% (Molmo)"],
    ["Video", "Video-MME", "33.7%", "42.2%", "52.1%", "45.0% (InternVL2)"],
    ["Video", "MLVU", "40.6%", "47.3%", "55.2%", "48.2% (InternVL2)"],
    [
      { text: "Average", options: { fill: { color: C.accent }, color: C.midnight, bold: true } },
      { text: "All Benchmarks", options: { fill: { color: C.accent }, color: C.midnight, bold: true } },
      { text: "44.0%", options: { fill: { color: C.accent }, color: C.midnight, bold: true } },
      { text: "51.0%", options: { fill: { color: C.accent }, color: C.midnight, bold: true } },
      { text: "59.8%", options: { fill: { color: C.accent }, color: C.midnight, bold: true } },
      { text: "—", options: { fill: { color: C.accent }, color: C.midnight, bold: true } },
    ],
  ];

  slide.addTable(tableData, {
    x: 0.4, y: 1.0, w: 9.2, h: 3.6,
    fontSize: 10, fontFace: "Calibri",
    color: C.darkText,
    border: { pt: 0.5, color: "CBD5E1" },
    colW: [1.4, 1.8, 1.1, 1.1, 1.1, 2.1],
    align: "center",
    valign: "middle",
    rowH: 0.26,
  });

  // RAM usage callout bar at bottom
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.75, w: 9.2, h: 0.6,
    fill: { color: C.midnight },
  });
  slide.addText("RAM Usage: 0.8 GB (256M)  |  1.2 GB (500M)  |  4.9 GB (2.2B)  —  vs. 27.7 GB for Molmo-A1B-7B", {
    x: 0.4, y: 4.75, w: 9.2, h: 0.6,
    fontSize: 13, fontFace: "Calibri", bold: true,
    color: C.white, align: "center", valign: "middle",
    margin: 0,
  });
}

// ============================================================
// SLIDE 8 — On-Device Deployment
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Real-Time Inference on iPhones: Up to 80 Tokens/Second on Apple Silicon", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Calibri", bold: true,
    color: C.midnight, align: "left", valign: "middle",
    margin: 0,
  });

  // Left: mobile app image
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.5, y: 1.2, w: 4.0, h: 3.6,
    sizing: { type: "contain", w: 4.0, h: 3.6 },
  });

  // Right: throughput stats
  const cardX = 4.8, cardW = 4.7;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.2, w: cardW, h: 3.6,
    fill: { color: C.white },
    shadow: shadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.2, w: 0.08, h: 3.6,
    fill: { color: C.primary },
  });
  slide.addText("Throughput Benchmarks", {
